const input = $input.first().json;
const action = input.action;
const params = input.params;
const requiredParams = input.required_params[action] || [];
const customAction = input.custom_actions[action];

// Si c'est une custom action, utiliser ses required_params
const finalRequiredParams = customAction?.required_params || requiredParams;

const missing = [];
const questions = [];

// Questions prédéfinies par paramètre
const paramQuestions = {
  "target_language": {
    "question": "Dans quelle langue veux-tu la traduction ?",
    "type": "text",
    "examples": "français, anglais, espagnol..."
  },
  "format": {
    "question": "Quel format de synthèse souhaites-tu ?",
    "type": "choice",
    "options": [
      { "value": "express", "label": "Résumé express (2-3 phrases)" },
      { "value": "points", "label": "Points clés (liste à puces)" },
      { "value": "structured", "label": "Résumé structuré (paragraphes)" },
      { "value": "outline", "label": "Plan détaillé (hiérarchique)" },
      { "value": "focused", "label": "Extraction ciblée (vous précisez)" }
    ]
  },
  "focus": {
    "question": "Sur quoi veux-tu te concentrer ?",
    "type": "text",
    "examples": "aspects juridiques, chiffres clés, recommandations..."
  },
  "output_format": {
    "question": "Quel format de sortie ?",
    "type": "choice",
    "options": [
      { "value": "json", "label": "JSON structuré" },
      { "value": "list", "label": "Liste texte" }
    ]
  },
  "target_system": {
    "question": "Vers quel système convertir les unités ?",
    "type": "choice",
    "options": [
      { "value": "metric", "label": "Métrique (g, ml, °C)" },
      { "value": "imperial", "label": "Impérial (oz, cups, °F)" }
    ]
  },
  "servings": {
    "question": "Pour combien de personnes ?",
    "type": "number",
    "default": 4
  }
};

// Vérifier chaque paramètre requis
for (const param of finalRequiredParams) {
  if (!params[param] || params[param] === '') {
    missing.push(param);
    questions.push({
      "param": param,
      ...paramQuestions[param] || {
        "question": `Veuillez fournir: ${param}`,
        "type": "text"
      }
    });
  }
}

return {
  json: {
    valid: missing.length === 0,
    can_proceed: missing.length === 0,
    missing: missing,
    errors: [],
    questions: questions,
    action: action,
    params: params,
    is_custom_action: !!customAction,
    custom_webhook_url: customAction?.webhook_url || null
  }
};

parameters.content:
## MCP - Documents Validate (RFC-014)

**Endpoint:** POST /webhook/documents/validate

**Purpose:** Validate document processing parameters

**Input (RFC-014 structure):**
```json
{
  "context": {
    "file_url": "https://..." OR "file_base64": "...",
    "action": "translate|summarize|ocr",
    "params": { ... }
  },
  "plugin_context": { ... }
}
```

**Legacy Input (also supported):**
```json
{
  "file_url": "https://...",
  "action": "translate",
  "params": { ... }
}
```

**Output:**
- `valid`: boolean
- `can_proceed`: boolean  
- `missing`: array of missing params
- `questions`: array of questions to ask user
